305	function assertDecoderSender(event: Electron.IpcMainInvokeEvent | Electron.IpcMainEvent): void {
306	  if (!decoderWin || decoderWin.isDestroyed() || event.sender !== decoderWin.webContents) {
307	    throw new Error('IPC denied: sender is not the import decoder')
308	  }
309	  const frame = event.senderFrame
310	  if (!frame || frame.parent !== null || !decoderExpectedUrl || frame.url !== decoderExpectedUrl) {
311	    throw new Error('IPC denied: import decoder is not its expected main frame')
312	  }
313	}
