315	// Non-throwing twin of assertDecoderSender, for use inside ipcMain.on listeners. A synchronous throw in an
316	// ipcMain.on handler isn't caught by Electron like an ipcMain.handle throw is — it escalates to a
317	// main-process uncaughtException, which brings up the app's fatal crash dialog. So .on listeners must
318	// reject unauthorized senders by returning, never by throwing.
319	function isDecoderSender(event: Electron.IpcMainEvent): boolean {
320	  if (!decoderWin || decoderWin.isDestroyed() || event.sender !== decoderWin.webContents) return false
321	  const frame = event.senderFrame
322	  if (!frame || frame.parent !== null || !decoderExpectedUrl || frame.url !== decoderExpectedUrl) return false
