390	async function startImportDecoder(job: ImportJob): Promise<void> {
391	  let stat: ReturnType<typeof statSync>
392	  try {
393	    stat = statSync(job.sourcePath)
394	  } catch {
395	    throw new Error('The selected recording is no longer available. Choose it again to restart the import.')
396	  }
397	  if (stat.size !== job.sourceSizeBytes || stat.mtimeMs !== job.sourceMtimeMs) {
398	    throw new Error('The selected recording changed after import started. Choose it again to restart.')
399	  }
400	  const ffmpeg = bundledImportFfmpeg()
401	  if (ffmpeg) {
402	    // A transcription failure inside acceptDecodedChunk marks the job terminal and pumps the next FIFO
403	    // job synchronously (fail() -> pump() -> here), before this decoder's own onError callback — which
404	    // normally deletes the map entry — has had a chance to run. Reap any decoder whose job already
405	    // finished so it can't block the next job with a false "already active".
406	    for (const [id, stale] of ffmpegDecoders) {
407	      if (id === job.jobId) continue
408	      const staleState = importJobs?.get(id)?.state
409	      if (staleState === 'failed' || staleState === 'cancelled' || staleState === 'done' || staleState === undefined) {
410	        stale.cancel()
411	        ffmpegDecoders.delete(id)
412	      }
413	    }
414	    if (ffmpegDecoders.size) throw new Error('Another audio decoder is already active.')
415	    const decoder = startFfmpegDecode(ffmpeg, job.sourcePath, job.cursor, {
416	      onChunk: async (seq, samples) => {
417	        await importJobs?.acceptDecodedChunk(job.jobId, seq, 0, samples)
418	      },
419	      onComplete: async (totalChunks) => {
420	        // Release the process slot before finishDecoding pumps the next FIFO job.
421	        ffmpegDecoders.delete(job.jobId)
422	        await importJobs?.finishDecoding(job.jobId, totalChunks)
423	      },
424	      onError: async (error) => {
425	        ffmpegDecoders.delete(job.jobId)
426	        await importJobs?.failDecoder(job.jobId, error.message)
427	      }
428	    })
429	    ffmpegDecoders.set(job.jobId, decoder)
430	    return
431	  }
432	  if (decoderWin && !decoderWin.isDestroyed()) throw new Error('Another audio decoder is already active.')
433	
434	  decoderJobId = job.jobId
435	  closingDecoderJobId = null
